import {sceneParams,SCENE_PRESETS} from './scene-settings.js';
import {assertImageDimensions} from './capacity.js';
export function validateSceneRecipe(r,assertSource){if(!r||r.version!==1||r.engine!=='scene-light-v1')throw Error('Invalid scene recipe.');assertImageDimensions(r.width,r.height);assertSource(r.source);assertSource(r.regionsSource);if(r.peopleSource)assertSource(r.peopleSource);if(typeof r.bakedMask!=='boolean')throw Error('Invalid baked mask.');sceneParams(r.params);if(typeof r.originId!=='string'||typeof r.method!=='string'||r.method.length>200||!Array.isArray(r.lamps)||r.lamps.length>40||r.lamps.some(p=>!p||!Number.isFinite(p.x+p.y+p.radius)||p.x<0||p.x>1||p.y<0||p.y>1||p.radius<.001||p.radius>.3))throw Error('Invalid scene regions.');if(r.preset!==''&&!SCENE_PRESETS.some(p=>p.id===r.preset))throw Error('Invalid scene preset.');return r;}
